"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronDown, 
  CheckCircle2, 
  UploadCloud, 
  Clock, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  Heart, 
  AlertOctagon, 
  Trash2,
  ArrowRight,
  UserCheck
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [{ date: "2026-01-26", name: "Republic Day" }];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-50", requiresDoc: false },
  { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-50", requiresDoc: true },
  { id: "casual", label: "Casual", icon: Briefcase, balance: 6, color: "text-amber-600", bg: "bg-amber-50", requiresDoc: false },
  { id: "comp", label: "Comp Off", icon: Umbrella, balance: 3, color: "text-emerald-600", bg: "bg-emerald-50", requiresDoc: false },
  { id: "mat", label: "Maternity", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-50", requiresDoc: true },
  { id: "ber", label: "Bereave", icon: Heart, balance: 5, color: "text-slate-600", bg: "bg-slate-100", requiresDoc: false },
  { id: "lop", label: "L.O.P", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-50", requiresDoc: false },
];

const APPROVER_CHAIN = [
  { name: "Sarah J.", role: "Manager", avatar: "SJ", time: "4h" },
  { name: "HR Dept", role: "Audit", avatar: "HR", time: "24h" }
];

export default function CompactAbsencePortal() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range" | "multi">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [multiDates, setMultiDates] = useState<string[]>([]);
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  
  const dropdownRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- LOGIC ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "multi") {
      setMultiDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr].sort());
    } else if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
    } else {
      if (!range.start || (range.start && range.end)) setRange({ start: dateStr, end: "" });
      else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  const stats = useMemo(() => {
    let days = 0, deduction = 0;
    const checkDay = (dStr: string) => {
      const dObj = new Date(dStr);
      const isHoliday = HOLIDAYS.some(h => h.date === dStr);
      const isWeekend = dObj.getDay() === 0 || dObj.getDay() === 6;
      if (!isHoliday && !isWeekend) return 1;
      return 0;
    };

    if (mode === "multi") {
      days = multiDates.length;
      deduction = multiDates.reduce((acc, date) => acc + checkDay(date), 0);
    } else {
      if (!range.start || !range.end) return { days: 0, deduction: 0 };
      let cur = new Date(range.start);
      let end = new Date(range.end);
      while (cur <= end) {
        deduction += checkDay(cur.toISOString().split('T')[0]);
        days++;
        cur.setDate(cur.getDate() + 1);
      }
    }
    return { days, deduction };
  }, [range, multiDates, mode]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;
  const hasValidDates = useMemo(() => {
    if (mode === "multi") return multiDates.length > 0;
    return !!(range.start && range.end);
  }, [mode, range, multiDates]);

  const isFormValid = hasValidDates && (!selectedType.requiresDoc || !!file);

  return (
    <div className="flex h-screen w-full bg-[#F8FAFC] dark:bg-[#0B0F19] font-sans text-slate-800 dark:text-slate-200 overflow-hidden transition-colors duration-200">
      
      {/* --- LEFT: CALENDAR (75%) --- */}
      <div className="flex-1 flex flex-col p-3 gap-3 h-full min-w-0">
        
        {/* Header */}
        <div className="flex items-center justify-between shrink-0 bg-white dark:bg-slate-900 px-4 py-2.5 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-14">
           <div className="flex items-center gap-2.5">
              <div className="bg-blue-600 p-1.5 rounded-lg text-white"><CalendarIcon className="h-4 w-4" /></div>
              <div>
                <h1 className="text-sm font-bold text-slate-900 dark:text-white leading-tight">Absence Portal</h1>
                <p className="text-[10px] text-slate-500 dark:text-slate-400 leading-tight">Engineering Team</p>
              </div>
           </div>
           
           <div className="flex bg-slate-100 dark:bg-slate-800 p-0.5 rounded-lg border border-slate-200 dark:border-slate-700">
              {['single', 'range', 'multi'].map((m) => (
                <button 
                  key={m}
                  onClick={() => { setMode(m as any); setRange({start:"", end:""}); setMultiDates([]); }}
                  className={`px-3 py-1 rounded-md text-[10px] font-bold capitalize transition-all ${
                    mode === m 
                    ? "bg-white dark:bg-slate-700 shadow text-blue-600 dark:text-blue-400" 
                    : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                  }`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Calendar Canvas */}
        <div className="flex-1 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden relative">
           
           <div className="flex items-center justify-between px-5 py-3 border-b border-slate-100 dark:border-slate-800 shrink-0 h-12">
              <h2 className="text-sm font-bold text-slate-800 dark:text-white">January 2026</h2>
              {(range.start || multiDates.length > 0) && (
                <button 
                  onClick={() => { setMultiDates([]); setRange({start:"", end:""}); }}
                  className="flex items-center gap-1 text-[10px] font-bold text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 px-2 py-1 rounded transition-colors"
                >
                  <Trash2 className="h-3 w-3" /> Clear
                </button>
              )}
           </div>

           <div className="flex-1 p-4 overflow-y-auto">
              <div className="grid grid-cols-7 gap-1 h-full content-start">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-bold text-slate-400 dark:text-slate-600 uppercase mb-1">{d}</div>
                 ))}
                 
                 {[null, null, null].map((_, i) => <div key={`e-${i}`}/>)}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const holiday = HOLIDAYS.find(h => h.date === dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;

                    let isSelected = false, inRange = false;
                    if (mode === "multi") isSelected = multiDates.includes(dateStr);
                    else {
                        isSelected = range.start === dateStr || range.end === dateStr;
                        inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;
                    }

                    // --- COMPACT STYLING LOGIC ---
                    let btnClass = "border border-slate-50 dark:border-slate-800/50 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:border-blue-300 dark:hover:border-blue-700";
                    if (isSelected) btnClass = "bg-blue-600 border-blue-600 text-white shadow-sm z-10";
                    else if (inRange) btnClass = "bg-blue-50 dark:bg-blue-900/20 border-blue-100 dark:border-blue-800 text-blue-600 dark:text-blue-100";
                    else if (holiday) btnClass = "bg-rose-50 dark:bg-rose-900/10 border-rose-100 dark:border-rose-900/30 text-rose-600 dark:text-rose-400";
                    else if (isWeekend) btnClass = "bg-slate-50 dark:bg-slate-800/40 text-slate-400 dark:text-slate-600";

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         className={`relative h-14 rounded-lg text-left p-1.5 transition-all group ${btnClass}`}
                       >
                          <span className="text-xs font-bold leading-none">{day}</span>
                          {holiday && (
                            <span className={`absolute bottom-1 left-1 right-1 text-[8px] font-bold px-1 rounded truncate ${isSelected ? 'bg-white/20 text-white' : 'bg-rose-100 dark:bg-rose-900/40 text-rose-600 dark:text-rose-300'}`}>
                                {holiday.name}
                            </span>
                          )}
                          {isSelected && <span className="absolute top-1.5 right-1.5"><CheckCircle2 className="h-3 w-3" /></span>}
                       </button>
                    )
                 })}
              </div>
           </div>
        </div>
      </div>

      {/* --- RIGHT: SIDEBAR (25% / 320px Fixed) --- */}
      <div className="w-[320px] flex-none p-3 pl-0 flex flex-col gap-3 h-full">
         
         {/* 1. APPROVER CHAIN */}
         <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-3 shadow-sm shrink-0">
            <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-2">Approvers</h3>
            <div className="flex items-center gap-2">
               {APPROVER_CHAIN.map((p, i) => (
                  <React.Fragment key={i}>
                     <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-800 p-1.5 rounded-lg border border-slate-100 dark:border-slate-700 flex-1 min-w-0">
                        <div className="h-5 w-5 rounded-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 flex items-center justify-center text-[8px] font-bold shrink-0">{p.avatar}</div>
                        <div className="truncate">
                           <p className="text-[9px] font-bold text-slate-900 dark:text-white truncate">{p.name}</p>
                           <p className="text-[8px] text-slate-400">~{p.time}</p>
                        </div>
                     </div>
                     {i < APPROVER_CHAIN.length - 1 && <ArrowRight className="h-3 w-3 text-slate-300 shrink-0" />}
                  </React.Fragment>
               ))}
            </div>
         </div>

         {/* 2. MAIN FORM */}
         <div className="flex-1 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden">
            
            {/* Header / Dropdown */}
            <div className="p-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 shrink-0 space-y-3">
               <div className="relative" ref={dropdownRef}>
                  <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block">Leave Type</label>
                  <button 
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="w-full flex items-center justify-between bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg p-2.5 hover:border-blue-400 transition-colors"
                  >
                     <div className="flex items-center gap-2 overflow-hidden">
                        <div className={`p-1 rounded ${selectedType.bg} ${selectedType.color} shrink-0`}><selectedType.icon className="h-3 w-3" /></div>
                        <span className="text-xs font-bold text-slate-900 dark:text-white truncate">{selectedType.label}</span>
                     </div>
                     <span className="text-[9px] font-bold bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded text-slate-500 shrink-0">{selectedType.balance} Left</span>
                  </button>

                  {isDropdownOpen && (
                     <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl z-50 max-h-[200px] overflow-y-auto p-1 custom-scrollbar">
                        {LEAVE_TYPES.map(t => (
                           <button
                             key={t.id}
                             onClick={() => { setTypeId(t.id); setIsDropdownOpen(false); }}
                             className="w-full flex items-center justify-between p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded group"
                           >
                              <div className="flex items-center gap-2 truncate">
                                 <div className={`p-1 rounded ${t.bg} ${t.color}`}><t.icon className="h-3 w-3" /></div>
                                 <span className="text-xs font-bold text-slate-700 dark:text-slate-300 group-hover:text-slate-900 dark:group-hover:text-white">{t.label}</span>
                              </div>
                              <span className="text-[9px] font-bold text-slate-400">{t.balance}</span>
                           </button>
                        ))}
                     </div>
                  )}
               </div>

               <div className="flex justify-between bg-slate-100 dark:bg-slate-800/50 p-2.5 rounded-lg items-center">
                  <div className="text-center w-1/2 border-r border-slate-200 dark:border-slate-700 pr-2">
                     <p className="text-[9px] font-bold text-slate-400 uppercase">Selected</p>
                     <p className="text-xs font-black text-slate-900 dark:text-white">{stats.days} Days</p>
                  </div>
                  <div className="text-center w-1/2 pl-2">
                     <p className="text-[9px] font-bold text-slate-400 uppercase">Deduction</p>
                     <p className="text-xs font-black text-rose-500">-{stats.deduction} Days</p>
                  </div>
               </div>
            </div>

            {/* Inputs */}
            <div className="flex-1 p-3 space-y-3 overflow-y-auto">
               <div>
                  <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block">Reason</label>
                  <textarea 
                     className="w-full h-16 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-950 p-2 text-xs font-medium focus:ring-1 focus:ring-blue-500 outline-none resize-none"
                     placeholder="Optional..."
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                  />
               </div>

               {selectedType.requiresDoc && (
                  <div className="animate-in zoom-in-95">
                     <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block flex justify-between">
                        <span>Attachment</span> <span className="text-rose-500 dark:text-rose-400">* Required</span>
                     </label>
                     <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`border-2 border-dashed rounded-lg h-12 flex items-center justify-center cursor-pointer transition-colors gap-2 ${file ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20" : "border-slate-200 dark:border-slate-700 hover:border-blue-400"}`}
                     >
                        <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                        {file ? (
                           <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1"><CheckCircle2 className="h-3 w-3"/> {file.name.slice(0, 15)}...</span>
                        ) : (
                           <div className="flex items-center gap-1 text-slate-400">
                             <UploadCloud className="h-3 w-3" />
                             <span className="text-[9px] font-bold">Upload</span>
                           </div>
                        )}
                     </div>
                  </div>
               )}
            </div>
            
            {/* Submit */}
            <div className="p-3 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/30 shrink-0">
               <button 
                  disabled={!isFormValid}
                  className={`w-full py-2.5 rounded-lg font-bold text-xs shadow-sm transition-all flex items-center justify-center gap-2 ${
                    isFormValid 
                    ? "bg-slate-900 dark:bg-blue-600 text-white hover:bg-black dark:hover:bg-blue-500 hover:shadow-md" 
                    : "bg-slate-200 dark:bg-slate-800 text-slate-400 dark:text-slate-600 cursor-not-allowed"
                  }`}
               >
                  {isFormValid ? "Submit Request" : mode === 'range' && range.start && !range.end ? "Select End Date" : "Select Dates"}
               </button>
            </div>
         </div>
      </div>
    </div>
  );
}